                                   activeCategory.id === cat.id 
                                   ? 'bg-brand-green text-brand-gold border-brand-green shadow-xl' 
                                   : 'bg-gray-50 text-gray-400 border-transparent hover:border-brand-gold/30'
                                 }`}
                               >
