      setItinerary(result);
      setOriginalItinerary(JSON.parse(JSON.stringify(result))); 
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const updateItineraryItem = (id: string, field: keyof ItineraryItem, value: string) => {
